# Let me look at CONNECTIVITY of cells
# Maybe cells that are "connected" (adjacent) get similar output values?

# Check adjacency for 8 vs 6 positions in cols 1-6
print("Adjacency check for output values (same value adjacent):")
for r in range(8):
    for c in range(8):
        if demo2_output[r][c] > 0:
            right_val = demo2_output[r][c+1] if c+1 < 9 else 0
            down_val = demo2_output[r+1][c] if r+1 < 9 else 0
            if right_val > 0 and demo2_output[r][c] == right_val:
                print(f"({r},{c})={demo2_output[r][c]} adjacent to right ({r},{c+1})={right_val}")
            if down_val > 0 and demo2_output[r][c] == down_val and not right_val > 0:
                print(f"({r},{c})={demo2_output[r][c]} adjacent to down ({r+1},{c})={down_val}")

# Actually let me check for both directions and see patterns
print("\n\nHorizontal adjacencies (same value):")
horizontal_same = []
for r in range(9):
    for c in range(8):
        if demo2_output[r][c] == demo2_output[r][c+1] and demo2_output[r][c] > 0:
            horizontal_same.append((r, c))
print(horizontal_same)

print("\n\nVertical adjacencies (same value):")
vertical_same = []
for r in range(8):
    for c in range(9):
        if demo2_output[r][c] == demo2_output[r+1][c] and demo2_output[r][c] > 0:
            vertical_same.append((r, c))
print(vertical_same)

# So adjacent cells with same value form chains
# Let me see what the patterns look like for each color
print("\n\nPositions for each color (walk through):")
for color in [6, 7, 8]:
    positions = sorted((p) for p in [(r,c) for r in range(9) for c in range(9) if demo2_output[r][c] == color])
    print(f"\nColor {color} positions: {positions}")

# Check the diagonal (row + col) pattern more carefully
print("(row + col) for each color:")
for color in [6, 7, 8]:
    color_positions = [(r, c, r+c) for r in range(9) for c in range(9) if demo2_output[r][c] == color]
    print(f"\nColor {color}:")
    for pos in sorted(color_positions, key=lambda x: x[2]):
        print(f"  {pos}: {pos[2]}")

# Check if there's a threshold
print("\n\n(row + col) ranges:")
all_8_sums = sorted([p[2] for p in color_positions]) if color_positions else []
all_6_sums = sorted([p[2] for p in positions_6]) if positions_6 else []
all_7_sums = sorted([p[2] for p in positions_7]) if positions_7 else []

print(f"Color 8 sums: {all_8_sums}")
print(f"Color 6 sums: {all_6_sums}")
print(f"Color 7 sums: {all_7_sums}")

# Actually I think I see the pattern:
# 8: sums are 3, 4, 4, 5, 5, 7, 9 (mostly lower numbers, except 9)
# 6: sums are 2, 4, 6, 9, 6, 7, 8, 9, 10, 11, 9 (mostly middle numbers)
# 7: sums are 8, 10, 12, 13, 14, 15, 13 (mostly higher numbers)

# Let me verify:
test_split = []
for r in range(9):
    for c in range(9):
        if demo2_output[r][c] > 0:
            s = r + c
            if s <= 5:
                test_split.append("8")
            elif s <= 9:
                test_split.append("6")
            else:
                test_split.append("7")

